#!/usr/bin/env node
// Deterministic PHI-in-logs check for Frappe Python code. It finds calls whose output reaches a log file,
// the Error Log DocType, or a client-visible message, and fails when their arguments reference a PHI field.
//
// Sinks:  frappe.logger(...).<level>(), <x>.logger.<level>(), _logger().<level>(), logging.<level>(),
//         logger/log/LOG.<level>()  (debug, info, warning, warn, error, exception, critical)
//         frappe.log_error(), frappe.throw(), frappe.msgprint(), print(), log_access() (spice_lite audit)
// Rules (errors, exit 1):
//   phi-field     an argument references a PHI name as code: `self.mrn`, `doc.last_name`, `family`, `f"{identifier}"`.
//                 Words inside plain string literals do not count ("A patient with this MRN already exists" is fine).
//   whole-doc     an argument dumps a document or the request: `.as_dict()`, `get_valid_dict`, `frappe.form_dict`
//   more-info     frappe.logger(..., with_more_info=True): Frappe then appends frappe.form_dict to every line
// Output names the rule, file, line and the PHI name only; source code is not PHI, but keep the report short.
// Exit 0 = clean, 1 = findings, 2 = usage error.
//
// Usage (from AI-SDLC-frappe/):
//   node scripts/automation/check-phi-logging.mjs                              # sample-app/spice_lite, tests excluded
//   node scripts/automation/check-phi-logging.mjs path/to/app --include-tests
import { existsSync, readdirSync, readFileSync, statSync } from "node:fs";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "..", "..");
const DEFAULT_DIR = join(ROOT, "sample-app", "spice_lite");
// Field and parameter names that carry PHI in spice_lite (context/domain/spice-lite-glossary.md, PHI table).
export const PHI_NAMES = ["mrn", "first_name", "last_name", "birth_date", "family", "given", "identifier", "national_id", "phone", "mobile_no"];
const LEVELS = "debug|info|warning|warn|error|exception|critical";
const SINK = new RegExp(
  String.raw`(?:\bfrappe\.logger\([^)]*\)\.(?:${LEVELS})|\b(?:_?logger\(\)|logger|log|LOG|logging)\.(?:${LEVELS})|\bfrappe\.(?:log_error|throw|msgprint)|(?<![\w.])print|(?<![\w.])log_access)\s*\(`,
  "g"
);

/** Return the text between the "(" at `open` and its matching ")", or null. Skips string literals. */
function argsAt(src, open) {
  let depth = 0;
  for (let i = open; i < src.length; i++) {
    const c = src[i];
    if (c === "#") {
      const nl = src.indexOf("\n", i);
      i = nl < 0 ? src.length : nl;
      continue;
    }
    if (c === '"' || c === "'") {
      const triple = src.startsWith(c.repeat(3), i);
      const q = triple ? c.repeat(3) : c;
      let j = i + q.length;
      while (j < src.length && !src.startsWith(q, j)) j += src[j] === "\\" ? 2 : 1;
      i = j + q.length - 1;
      continue;
    }
    if (c === "(") depth++;
    else if (c === ")" && --depth === 0) return src.slice(open + 1, i);
  }
  return null;
}

/** Remove plain string literal contents; keep the {expressions} of f-strings. */
export function codeOnly(args) {
  return args.replace(/([rRbBuU]?[fF]?[rR]?)("""|'''|"|')((?:\\.|(?!\2)[\s\S])*?)\2/g, (m, prefix, q, body) =>
    /f/i.test(prefix) ? ` ${[...body.matchAll(/\{([^{}]*)\}/g)].map((x) => x[1]).join(" ")} ` : ' "" '
  );
}

export function checkSource(src, file = "<input>") {
  const findings = [];
  const lineOf = (i) => src.slice(0, i).split("\n").length;
  for (const m of src.matchAll(SINK)) {
    const open = m.index + m[0].length - 1;
    const args = argsAt(src, open);
    if (args === null) continue;
    const code = codeOnly(args);
    const sink = m[0].replace(/\s*\($/, "");
    for (const name of PHI_NAMES) {
      if (new RegExp(String.raw`(?<![\w"'])${name}\b(?!\s*=[^=])`).test(code))
        findings.push({ rule: "phi-field", file, line: lineOf(m.index), sink, name });
    }
    if (/\.as_dict\(|get_valid_dict|\bform_dict\b/.test(code)) findings.push({ rule: "whole-doc", file, line: lineOf(m.index), sink, name: code.match(/as_dict|get_valid_dict|form_dict/)[0] });
  }
  for (const m of src.matchAll(/\bfrappe\.logger\s*\(/g)) {
    const args = argsAt(src, m.index + m[0].length - 1) || "";
    if (/with_more_info\s*=\s*True/.test(args)) findings.push({ rule: "more-info", file, line: lineOf(m.index), sink: "frappe.logger", name: "with_more_info=True" });
  }
  return findings;
}

function pyFiles(dir, includeTests) {
  const out = [];
  const walk = (d) => {
    for (const f of readdirSync(d)) {
      if (f.startsWith(".") || f === "node_modules" || f === "__pycache__") continue;
      if (!includeTests && (f === "tests" || /^test_.*\.py$/.test(f))) continue;
      const p = join(d, f);
      if (statSync(p).isDirectory()) walk(p);
      else if (f.endsWith(".py")) out.push(p);
    }
  };
  walk(dir);
  return out.sort();
}

function main(argv) {
  const includeTests = argv.includes("--include-tests");
  const targets = argv.filter((a) => !a.startsWith("--"));
  if (argv.some((a) => a.startsWith("--") && a !== "--include-tests")) {
    console.error("usage: check-phi-logging.mjs [--include-tests] [DIR_OR_FILE...]");
    return 2;
  }
  const paths = (targets.length ? targets.map((t) => resolve(t)) : [DEFAULT_DIR]).flatMap((p) => {
    if (!existsSync(p)) return [];
    return statSync(p).isDirectory() ? pyFiles(p, includeTests) : [p];
  });
  if (!paths.length) {
    console.error("no Python files found");
    return 2;
  }
  const findings = paths.flatMap((p) => checkSource(readFileSync(p, "utf8"), relative(ROOT, p).startsWith("..") ? p : relative(ROOT, p)));
  for (const f of findings) console.log(`ERROR  ${f.rule}: ${f.file}:${f.line}: ${f.sink}(...) references ${f.name}`);
  console.log(findings.length ? `FAIL: ${findings.length} PHI logging finding(s) in ${paths.length} file(s)` : `PASS: ${paths.length} Python file(s), no PHI reaches a log, Error Log or message`);
  return findings.length ? 1 : 0;
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) process.exit(main(process.argv.slice(2)));

#!/usr/bin/env node
// Deterministic PHI scanner for text: handoff files, ticket summaries, PR bodies, and Frappe log files
// (<bench>/logs/*.log, sites/<site>/logs/*.log). Regexes, not judgement: the same input always gives the same
// answer, so it can gate a workflow step or a CI job. It finds identifiers with a fixed shape; it cannot
// recognise a bare person name, which is why the ticket-intake skill also redacts names by instruction.
//
// Kinds: MRN (except synthetic MRN-000xxx), NATIONAL_ID (labelled), DOB (labelled), EMAIL (except example.com/.org,
// *.test, localhost), PHONE (international +CC..., Kenyan 07xx/01xx, US style), NAME ("Patient name: X Y"),
// FIELD (a PHI field serialised with a value, e.g. 'last_name': 'Kamau' or "family": "Otieno", which is what
// frappe.logger(..., with_more_info=True) writes when it appends frappe.form_dict).
//
// Usage (from AI-SDLC-frappe/):
//   node scripts/automation/scan-phi.mjs FILE...                    # exit 1 if anything is found
//   node scripts/automation/scan-phi.mjs --fix FILE...              # rewrite FILE with [REDACTED-*] tokens, then rescan
//   node scripts/automation/scan-phi.mjs --ignore EMAIL FILE...     # e.g. audit logs, which record staff users
//   cat notes.txt | node scripts/automation/scan-phi.mjs -          # scan stdin
// Exit 0 = clean, 1 = PHI-shaped content found, 2 = usage error.
// Findings print kind, line and length only, never the matched value, so the output is safe to paste.
import { readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";

const SYNTHETIC_VALUE = String.raw`(?:Test|Patient|Test Patient|MRN-000\d{3}|\[REDACTED[^\]]*\])`;
export const RULES = [
  { kind: "MRN", re: /\bMRN[-\s:#]*(?!000\d{3}\b)\d{4,10}\b/gi },
  { kind: "NATIONAL_ID", re: /\b(?:national[ _-]?id|id(?:entity)?[ _-]?(?:no|number)|huduma(?: number)?)\.?\s*[:#=]?\s*\d{6,10}\b/gi },
  { kind: "DOB", re: /\b(?:dob|date of birth|birth[ _]?date|born(?: on)?)["']?\s*[:=]?\s*["']?\d{1,4}[-/.]\d{1,2}[-/.]\d{1,4}\b/gi },
  { kind: "EMAIL", re: /\b[A-Za-z0-9._%+-]+@(?!example\.(?:com|org)\b)(?![A-Za-z0-9.-]*\.test\b)(?!localhost\b)[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b/g },
  {
    kind: "PHONE",
    re: /(?<![\w-])(?:\+\d{1,3}[\s.-]?\d{2,4}(?:[\s.-]?\d{2,4}){2,3}|0[17]\d{2}[\s.-]?\d{3}[\s.-]?\d{3}|\(?\d{3}\)?[\s.-]\d{3}[\s.-]\d{4})(?![\w-])/g,
  },
  { kind: "NAME", re: /\b(?:patient(?: name)?|pt|name)\s*[:=]\s*(?!Test Patient\b)(?!\[REDACTED)[A-Z][a-z]+(?:[ ,]+[A-Z][a-z]+)+/g },
  {
    kind: "FIELD",
    re: new RegExp(
      String.raw`["']?\b(?:mrn|first_name|last_name|birth_date|family|given|identifier|national_id)["']?\s*[:=]\s*["'](?!${SYNTHETIC_VALUE}["'])[^"'\n]{2,}["']`,
      "g"
    ),
  },
];

/** Returns [{ kind, line, match }] for one text. */
export function scan(text, ignore = []) {
  const findings = [];
  text.split("\n").forEach((line, i) => {
    for (const { kind, re } of RULES) {
      if (ignore.includes(kind)) continue;
      for (const m of line.matchAll(re)) findings.push({ kind, line: i + 1, match: m[0] });
    }
  });
  return findings;
}

/** Replace every finding with a [REDACTED-KIND] token, keeping labels so the sentence still reads. */
export function redact(text, ignore = []) {
  let out = text;
  for (const { kind, re } of RULES) {
    if (ignore.includes(kind)) continue;
    out = out.replace(re, (m) => {
      if (kind === "FIELD") return m.replace(/(["'])[^"']*\1$/, (q) => `${q[0]}[REDACTED]${q[0]}`);
      const label = /^(\D*?[:=#]\s*)/.exec(m);
      return ["DOB", "NAME", "NATIONAL_ID"].includes(kind) ? `${label ? label[1] : ""}[REDACTED-${kind}]` : `[REDACTED-${kind}]`;
    });
  }
  return out;
}

function main(argv) {
  const fix = argv.includes("--fix");
  const ignore = [];
  const files = [];
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === "--fix") continue;
    if (argv[i] === "--ignore") ignore.push(...(argv[++i] || "").split(",").map((s) => s.trim().toUpperCase()));
    else files.push(argv[i]);
  }
  if (files.length === 0 || ignore.some((k) => !RULES.some((r) => r.kind === k))) {
    console.error(`usage: scan-phi.mjs [--fix] [--ignore ${RULES.map((r) => r.kind).join(",")}] FILE... | -`);
    return 2;
  }
  let total = 0;
  for (const f of files) {
    const text = f === "-" ? readFileSync(0, "utf8") : readFileSync(f, "utf8");
    if (fix && f !== "-") {
      const before = scan(text, ignore).length;
      writeFileSync(f, redact(text, ignore));
      if (before) console.log(`${f}: redacted ${before} finding(s)`);
    }
    const findings = scan(fix && f !== "-" ? readFileSync(f, "utf8") : text, ignore);
    for (const x of findings) console.log(`${f}:${x.line}: ${x.kind} (${x.match.length} chars)`);
    total += findings.length;
  }
  console.log(total ? `FAIL: ${total} PHI-shaped value(s) found` : "PASS: no PHI-shaped values found");
  return total ? 1 : 0;
}

if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href) process.exit(main(process.argv.slice(2)));

#!/usr/bin/env node
// Tests for the deterministic automation scripts. Run from AI-SDLC-frappe/: node --test scripts/automation/automation.test.mjs
// Every test that mutates something works on a temporary copy or a temporary git repo; the real app is only read.
import { test } from "node:test";
import assert from "node:assert/strict";
import { execFileSync, spawnSync } from "node:child_process";
import { mkdtempSync, mkdirSync, writeFileSync, rmSync, readFileSync, cpSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { checkPatches, parsePatches } from "./check-patches.mjs";
import { lintDoctype, lintFiles, scrub } from "./lint-doctype-json.mjs";
import { checkSource } from "./check-phi-logging.mjs";
import { scan, redact } from "./scan-phi.mjs";
import { checkMcpConfig } from "./check-mcp-config.mjs";

const HERE = dirname(fileURLToPath(import.meta.url));
const ROOT = join(HERE, "..", "..");
const APP = join(ROOT, "sample-app", "spice_lite", "spice_lite");
const POLICY = JSON.parse(readFileSync(join(HERE, "doctype-policy.json"), "utf8"));
const node = (script, args = []) => spawnSync(process.execPath, [join(HERE, script), ...args], { encoding: "utf8" });

// ---------------------------------------------------------------- check-patches
const BASE_PATCHES = "[pre_model_sync]\n# comment\n\n[post_model_sync]\nmyapp.patches.v0_1.backfill_country\n";
function appRepo() {
  const root = mkdtempSync(join(tmpdir(), "patches-"));
  const app = join(root, "myapp", "myapp");
  mkdirSync(join(app, "patches", "v0_1"), { recursive: true });
  mkdirSync(join(app, "patches", "v0_2"), { recursive: true });
  writeFileSync(join(app, "patches.txt"), BASE_PATCHES);
  writeFileSync(join(app, "patches", "v0_1", "backfill_country.py"), "def execute():\n\tpass\n");
  const g = (...a) => execFileSync("git", ["-c", "user.email=t@example.com", "-c", "user.name=t", ...a], { cwd: root, stdio: "ignore" });
  g("init", "-q");
  g("add", ".");
  g("commit", "-q", "-m", "v0.1");
  const patch = (name, body = "def execute():\n\tpass\n") => writeFileSync(join(app, "patches", "v0_2", `${name}.py`), body);
  const setTxt = (t) => writeFileSync(join(app, "patches.txt"), t);
  return { app, patch, setTxt, done: () => rmSync(root, { recursive: true, force: true }) };
}

test("patches: the real spice_lite patches.txt passes", () => {
  const r = node("check-patches.mjs");
  assert.equal(r.status, 0, r.stdout);
  assert.match(r.stdout, /OK     ok post_model_sync spice_lite\.patches\.v0_1\.backfill_patient_country/);
  assert.match(r.stdout, /PASS: patches\.txt valid against HEAD/);
});

test("patches: a new patch appended at the end of its section passes", () => {
  const t = appRepo();
  t.patch("index_observation_effective_datetime");
  t.setTxt(BASE_PATCHES + "myapp.patches.v0_2.index_observation_effective_datetime\n");
  const r = checkPatches({ app: t.app });
  assert.deepEqual(r.errors, []);
